<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stamp Safari · Chloe Reads Jon</title><style>
:root{--ink:#25362e;--pine:#244f42;--cream:#fff8df;--orange:#e86635;--line:#b9a777}*{box-sizing:border-box}body{margin:0;color:var(--ink);font-family:Georgia,'Times New Roman',serif;background:#e8d9ad;background-image:radial-gradient(#956d3525 1px,transparent 1px);background-size:14px 14px}button{font:inherit;cursor:pointer}a{color:var(--pine)}.wrap{max-width:1150px;margin:auto;padding:18px 18px 60px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;font:700 12px 'Trebuchet MS',sans-serif;letter-spacing:.17em;text-transform:uppercase}.top a{text-decoration:none}.tag{border:1px solid var(--ink);border-radius:99px;padding:9px 14px;background:#f8edc7}h1{font-size:clamp(3.5rem,9vw,7rem);letter-spacing:-.075em;line-height:.89;margin:30px 0 14px;color:var(--pine);text-shadow:3px 4px #fff9e6}.intro{font-size:clamp(1rem,2.5vw,1.3rem);line-height:1.5;max-width:690px;margin:0 0 25px}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:18px}.panel,.stage{background:var(--cream);border:2px solid var(--ink);box-shadow:7px 7px 0 #243f34;padding:15px}.panel h2{margin:2px 0 12px;font-size:1.55rem;letter-spacing:-.04em}.eyebrow{font:800 11px 'Trebuchet MS',sans-serif;text-transform:uppercase;letter-spacing:.15em;color:#746447}.progress{display:flex;gap:5px;margin:10px 0 17px}.dot{width:24px;height:9px;border:1px solid var(--pine);background:transparent}.dot.done{background:#ed793e}.mission{background:#f1e3b8;border:1px solid var(--line);padding:13px;min-height:112px;line-height:1.4}.mission strong{display:block;margin-bottom:7px}.tools{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:12px}.tool{border:1.5px solid var(--pine);background:#fffaf0;min-height:64px;padding:6px;font-size:1.55rem;transition:transform .15s,background .15s}.tool span{display:block;font:700 11px 'Trebuchet MS',sans-serif;letter-spacing:.05em}.tool.active{background:#e8b85a;transform:rotate(-3deg);box-shadow:3px 3px 0 var(--ink)}.tool:hover{transform:translateY(-3px)}.scene{position:relative;aspect-ratio:3/2;background:#f3d49a;overflow:hidden;border:3px solid var(--ink);touch-action:none}.scene img,.scene canvas{position:absolute;inset:0;width:100%;height:100%}.scene img{object-fit:cover}.scene canvas{touch-action:none;cursor:crosshair}.caption{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:12px 0 0;font:700 11px 'Trebuchet MS',sans-serif;text-transform:uppercase;letter-spacing:.09em}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.actions button{border:1.5px solid var(--ink);padding:10px 13px;background:#fff3d1;font-size:.9rem;font-weight:bold}.actions button.primary{background:#ec7645;color:#201d17}.actions button:hover{filter:brightness(.93)}.status{background:#fff8df;border-left:5px solid var(--orange);margin-top:18px;padding:13px 15px;line-height:1.45;min-height:50px}.footer{border-top:1px solid #998d69;margin-top:42px;padding-top:15px;line-height:1.5;font-size:.9rem}.confetti{animation:pop .4s ease-out}@keyframes pop{50%{transform:scale(1.04)}}@media(max-width:750px){.layout{grid-template-columns:1fr}.panel{order:2}.stage{order:1}.tools{grid-template-columns:repeat(4,1fr)}.scene{aspect-ratio:3/2}.caption{font-size:10px}h1{margin-top:24px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}
</style></head><body><div class="wrap"><div class="top"><a href="index.php">← Chloe Reads Jon</a><span class="tag">Field guide no. 01 / make a mess</span></div><header><h1>Stamp<br>Safari<span style="color:#e56c3d">.</span></h1><p class="intro">A little hide-and-seek inside a painting. Choose the right stamp, put it where the clue points, and turn your safari into a postcard. No drawing talent required. Absolutely no sensible restraint encouraged.</p></header><main class="layout"><aside class="panel"><div class="eyebrow">Today's expedition</div><h2>Find their places</h2><div class="progress" id="progress" aria-label="Mission progress"></div><div class="mission" id="mission" aria-live="polite"></div><div class="eyebrow" style="margin-top:18px">Your stamp case</div><div class="tools" id="tools"></div><p style="font-size:.84rem;line-height:1.4">Pick a stamp, then tap the picture. After the five clues, keep decorating as long as you like.</p></aside><section class="stage"><div class="scene" id="scene"><img id="meadow" src="stamp-safari-meadow.webp" alt="An original storybook meadow with a cottage, a tree, hills and an open sky"><canvas id="paint" width="900" height="600" aria-label="Interactive safari picture; choose a stamp then tap to place it"></canvas></div><div class="caption"><span>✦ Tap anywhere in the landscape</span><span id="counter">0 / 5 discoveries</span></div><div class="actions"><button id="undo" type="button">↶ Undo</button><button id="redo" type="button">↷ Redo</button><button id="sound" type="button" aria-pressed="false">♫ Sound off</button><button id="reset" type="button">New safari</button><button class="primary" id="save" type="button">Save postcard ↓</button></div><div class="status" id="status" role="status">First clue: pick a stamp from the case.</div></section></main><footer class="footer">Inspired by Jon's <a href="https://jona.ca/2006/02/tuxpaint-too-much-fun.html" target="_blank" rel="noopener">TuxPaint -- too much fun</a>: especially the zany stamps and the pleasure of noodling with a picture just because. This little version stays in your browser; nothing you make is uploaded.</footer></div><script>
(()=>{'use strict';const C=document.getElementById('paint'),ctx=C.getContext('2d'),scene=document.getElementById('scene'),status=document.getElementById('status'),missionEl=document.getElementById('mission'),prog=document.getElementById('progress'),counter=document.getElementById('counter');const stamps=[['bird','🐦','Bird'],['flower','✿','Flower'],['sun','☀','Sun'],['car','🚗','Car'],['star','★','Star'],['mushroom','🍄','Mushroom'],['heart','♥','Heart'],['rainbow','🌈','Rainbow']];const quests=[{key:'bird',area:p=>p.x<.39&&p.y<.58,clue:'A little visitor wants a perch.',where:'Put a bird near the big tree, on the left side.'},{key:'flower',area:p=>p.y>.68,clue:'The field looks a little lonely.',where:'Plant a flower in the lower meadow.'},{key:'sun',area:p=>p.y<.39,clue:'Something warm belongs overhead.',where:'Place the sun high in the sky.'},{key:'car',area:p=>p.y>.62,clue:'Someone is taking the scenic route.',where:'Park a car low by the path.'},{key:'star',area:p=>p.y<.42,clue:'A surprise in broad daylight!',where:'Hide a star in the sky.'}];let selected='bird',items=[],history=[],complete=0,sound=false,audio;function note(s){status.textContent=s}function chirp(i){if(!sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(330+i*43,audio.currentTime);o.frequency.exponentialRampToValueAtTime(650+i*90,audio.currentTime+.11);g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.19);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.2)}catch(e){}}function ui(){document.getElementById('tools').innerHTML=stamps.map(([k,ico,name])=>'<button type="button" class="tool '+(selected===k?'active':'')+'" data-stamp="'+k+'" aria-label="Select '+name+' stamp" aria-pressed="'+(selected===k)+'">'+ico+'<span>'+name+'</span></button>').join('');prog.innerHTML=quests.map((_,i)=>'<span class="dot '+(i<complete?'done':'')+'"></span>').join('');missionEl.innerHTML=complete===5?'<strong>Field guide complete!</strong>The meadow is yours now. Add any stamps you want, then save a postcard.': '<strong>Clue '+(complete+1)+' / 5 · '+quests[complete].clue+'</strong>'+quests[complete].where;counter.textContent=complete+' / 5 discoveries'}function draw(){ctx.clearRect(0,0,900,600);items.forEach((it,i)=>{const x=it.x*900,y=it.y*600;ctx.save();ctx.translate(x,y);ctx.rotate(it.rot);ctx.shadowColor='#45362570';ctx.shadowBlur=6;ctx.shadowOffsetY=5;ctx.font=(it.key==='flower'||it.key==='sun'||it.key==='star'||it.key==='heart'?'bold ':'')+it.size+'px Georgia,serif';ctx.textAlign='center';ctx.textBaseline='middle';let glyph=stamps.find(s=>s[0]===it.key)[1];if(['flower','sun','star','heart'].includes(it.key)){ctx.fillStyle=({flower:'#e44f50',sun:'#f5ac32',star:'#ffe070',heart:'#e96069'})[it.key];ctx.strokeStyle='#4a3b31';ctx.lineWidth=2;ctx.strokeText(glyph,0,0);ctx.fillText(glyph,0,0)}else ctx.fillText(glyph,0,0);ctx.restore()})}function put(e){const r=C.getBoundingClientRect(),p={x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};history=[];items.push({...p,key:selected,before:complete,size:61+Math.random()*22,rot:(Math.random()-.5)*.24});draw();chirp(items.length%6);if(complete<5){const q=quests[complete];if(selected===q.key&&q.area(p)){complete++;scene.classList.remove('confetti');void scene.offsetWidth;scene.classList.add('confetti');note(complete===5?'Safari complete! Make it wonderfully crowded, or save your postcard.':'Found it! '+quests[complete].clue);ui()}else note('A lovely stamp! For this clue, try '+stamps.find(s=>s[0]===q.key)[2].toLowerCase()+' '+(selected===q.key?'somewhere else.':'first.'))}else note('Excellent addition. The meadow was clearly missing that.')}document.getElementById('tools').addEventListener('click',e=>{const b=e.target.closest('[data-stamp]');if(!b)return;selected=b.dataset.stamp;ui();note('Selected '+stamps.find(s=>s[0]===selected)[2]+'. Now tap the picture!')});C.addEventListener('pointerdown',put);document.getElementById('undo').onclick=()=>{if(!items.length)return;const item=items.pop();history.push({item,complete});complete=item.before;draw();ui();note('One stamp back in the case.')};document.getElementById('redo').onclick=()=>{const h=history.pop();if(!h)return;items.push(h.item);complete=h.complete;draw();ui();note('Welcome back, little stamp.')};document.getElementById('reset').onclick=()=>{if(items.length&&!confirm('Start a fresh safari? Your current picture will be cleared.'))return;items=[];history=[];complete=0;draw();ui();note('Fresh meadow, fresh expedition!')};document.getElementById('sound').onclick=e=>{sound=!sound;e.currentTarget.textContent=sound?'♫ Sound on':'♫ Sound off';e.currentTarget.setAttribute('aria-pressed',String(sound));chirp(3)};document.getElementById('save').onclick=()=>{const img=document.getElementById('meadow');const out=document.createElement('canvas');out.width=900;out.height=600;const o=out.getContext('2d');o.fillStyle='#f5d59d';o.fillRect(0,0,900,600);if(img.complete&&img.naturalWidth){const ratio=Math.max(900/img.naturalWidth,600/img.naturalHeight),w=img.naturalWidth*ratio,h=img.naturalHeight*ratio;o.drawImage(img,(900-w)/2,(600-h)/2,w,h)}o.drawImage(C,0,0);const a=document.createElement('a');a.download='stamp-safari-postcard.png';a.href=out.toDataURL('image/png');a.click();note('Postcard saved. The expedition is officially documented.')};ui();})();
</script></body></html>